const currentPath = window.location.pathname;

if (currentPath.includes("/blog")) {
  initializeFilterSwiper();
} else if (currentPath.includes("/qui-sommes-nous")) {
  initializeTeamSwiper();
}

function initializeFilterSwiper() {
  jQuery(".slick-slider").slick({
    infinite: false,
    slidesToShow: 10,
    slidesToScroll: 3,
    centerMode: false,
    variableWidth: true,
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 6,
          slidesToScroll: 3,
        },
      },
      {
        breakpoint: 600,
        settings: {
          slidesToShow: 3,
          slidesToScroll: 3,
        },
      },
    ],
  });
}

function initializeTeamSwiper() {
  jQuery(".slick-slider").slick({
    infinite: false,
    slidesToShow: 3,
    slidesToScroll: 3,
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 2,
          slidesToScroll: 2,
        },
      },
      {
        breakpoint: 600,
        settings: {
          slidesToShow: 1,
          slidesToScroll: 1,
        },
      },
    ],
  });
}
